CREATE DATABASE shop;
\c shop

CREATE TABLE orders (
    order_id    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer_id integer NOT NULL,
    status      text    NOT NULL,
    amount      numeric(10,2) NOT NULL,
    created_at  timestamptz NOT NULL
);

INSERT INTO orders (customer_id, status, amount, created_at)
SELECT (random() * 50000)::int + 1,
       (ARRAY['new','paid','shipped','cancelled'])[1 + (g % 4)],
       round((random() * 5000)::numeric, 2),
       now() - (g || ' minutes')::interval
  FROM generate_series(1, 2000000) AS g;

ANALYZE orders;

CREATE ROLE shop_app LOGIN PASSWORD 'Shop#2026';
GRANT SELECT, INSERT, UPDATE, DELETE ON orders TO shop_app;

SELECT pg_reload_conf();

-- in a NEW session, a moment later:
SELECT name, setting, unit
  FROM pg_settings
 WHERE name IN ('log_min_duration_statement', 'log_lock_waits', 'log_temp_files')
 ORDER BY name;

\timing on
SELECT status, count(DISTINCT customer_id) AS customers
  FROM orders
 GROUP BY status;

SELECT * FROM orders WHERE order_id = 42;

